(34911, 'Mark 3:29', 'Mark', 3, 29, 'خو څوک چې د روح القدس په خلاف کفر ووایي هغه به هېڅکله ونه بخښل شي، بلکې د هغې ګناه به تل ترتله د هغه په غاړه وي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_29.mp3', '', 1761754199, 1761754199),
(34912, 'Mark 3:30', 'Mark', 3, 30, 'عیسی ځکه دا خبره وکړه چې هغوی ویل: «هغه پېریانو نیولی دی.» د عیسی مور او ورونه (متي ۱۲‏:‌۴۶‌‏-‌۵۰ او لوقا ۸‏:‌۱۹‌‏-‌۲۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_30.mp3', '', 1761754199, 1761754199),
(34913, 'Mark 3:31', 'Mark', 3, 31, 'بیا د عیسی مور او ورونه راغلل او د کور څخه دباندې ولاړ وو. هغوی یو څوک ورولېږه چې هغه ته غږ وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_31.mp3', '', 1761754199, 1761754199),
(34914, 'Mark 3:32', 'Mark', 3, 32, 'په دې وخت کې ګڼ شمېر خلک چې د عیسی چارچاپېره ناست وو، هغه ته وویل: «ستا مور او ورونه دباندې ولاړ دي او غواړي چې تا وویني.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_32.mp3', '', 1761754199, 1761754199),
(34915, 'Mark 3:33', 'Mark', 3, 33, 'عیسی په ځواب کې وویل: «زما مور څوک ده او زما ورونه څوک دي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_33.mp3', '', 1761754199, 1761754199),
(34916, 'Mark 3:34', 'Mark', 3, 34, 'عیسی هغو خلکو ته چې د هغه چارچاپېره ناست وو وکتل او ویې ویل: «زما مور او زما ورونه دا دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_34.mp3', '', 1761754199, 1761754199),
(34917, 'Mark 3:35', 'Mark', 3, 35, 'څوک چې د خدای د ارادې سره سم کار کوي هغه زما ورور، زما خور او زما مور ده.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark3_verse_35.mp3', '', 1761754199, 1761754199),
(34918, 'Acts 22:1', 'Acts', 22, 1, 'پولوس هغوی ته وویل: «ای زما یهودي ورونو او پلرونو! زه چې اوس تاسو ته د خپل ځان څخه د دفاع دپاره څه وایم، ورته غوږ ونیسئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_1.mp3', '', 1761754199, 1761754199),
(34919, 'Acts 22:2', 'Acts', 22, 2, 'کله چې هغوی واورېدل پولوس په عبراني ژبه خبرې کوي، نو هغوی نور هم غلي شول. بیا پولوس وویل:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_2.mp3', '', 1761754199, 1761754199),
(34920, 'Acts 22:3', 'Acts', 22, 3, '«زه یهودي یم او د قیلیقیې په ترسوس کې پیدا شوی یم، خو دلته په اورشلیم کې لوی شوی یم او د غمالاییل شاګرد وم. د هغه څخه مې په ډېرې سختې طریقې سره زده کړل چې څنګه د خپلو نیکونو د شریعت څخه پیروي وکړم او په غیرت او شوق سره مې د خدای خدمت وکړ لکه څنګه چې تاسو یې کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_3.mp3', '', 1761754199, 1761754199),
(34921, 'Acts 22:4', 'Acts', 22, 4, 'ما د مرګ تر حده د څښتن عیسی مسیح د لارې پیروان ځورول. ښځې او نران دواړه به مې نیول او په زندان کې به مې اچول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_4.mp3', '', 1761754199, 1761754199),
(34922, 'Acts 22:5', 'Acts', 22, 5, 'لوی کاهن او د یهودیانو د شورا ټول غړي کولای شي شاهدي ورکړي چې زه رښتیا وایم. هغوی ماته په دمشق کې د یهودي ورونو دپاره رسمي لیکونه راکړي وو. نو زه دمشق ته لاړم چې هغه خلک لاس تړلي اورشلیم ته راولم چې سزا ورته ورکړل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_5.mp3', '', 1761754199, 1761754199),
(34923, 'Acts 22:6', 'Acts', 22, 6, 'کله چې زه په سفر روان وم او دمشق ته نژدې شوم او د غرمې وخت نژدې ؤ، نو ناڅاپه د اسمان څخه یوه لویه رڼا زما شاوخوا وځلېدله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_6.mp3', '', 1761754199, 1761754199),
(34924, 'Acts 22:7', 'Acts', 22, 7, 'زه په ځمکه راولوېدم او یو اواز مې واورېد چې ویل یې: ‹شاووله، شاووله! ته ولې ما ځوروې؟›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_7.mp3', '', 1761754199, 1761754199),
(34925, 'Acts 22:8', 'Acts', 22, 8, 'ما پوښتنه وکړه: ‹ای څښتنه، ته څوک یې؟› هغه ځواب راکړ: ‹زه ناصري عیسی یم، یعنې هغه څوک چې ته یې ځوروې.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_8.mp3', '', 1761754199, 1761754199),
(34926, 'Acts 22:9', 'Acts', 22, 9, 'زما ملګرو رڼا ولیدله، خو چا چې زما سره خبرې کولې د هغه اواز یې نه اورېدلو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_9.mp3', '', 1761754199, 1761754199),
(34927, 'Acts 22:10', 'Acts', 22, 10, 'ما پوښتنه وکړه: ‹څښتنه، زه څه وکړم؟› څښتن راته وویل: ‹پاڅېږه او دمشق ته لاړ شه. کله چې هلته ورسېدلې، نو په هغه ځای کې به د هغو ټولو کارونو په هکله چې ستا دپاره ټاکل شوي دي، درته وویل شي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_10.mp3', '', 1761754199, 1761754199),
(34928, 'Acts 22:11', 'Acts', 22, 11, 'زه د هغې سختې رڼا له لاسه ړوند شوی وم، نو ملګرو مې له لاسه ونیولم او دمشق ته یې بوتلم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_11.mp3', '', 1761754199, 1761754199),
(34929, 'Acts 22:12', 'Acts', 22, 12, 'په هغه ښار کې یو سړی اوسېده چې حنانیا نومېده چې یو پرهېزګاره او په شریعت باندې ټینګ ولاړ ؤ او د هغه ځای ټولو یهودیانو د هغه ډېر درناوی کاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_12.mp3', '', 1761754199, 1761754199),
(34930, 'Acts 22:13', 'Acts', 22, 13, 'هغه راغی، زما په څنګ کې ودرېده او ویې ویل: ‹ای شاووله وروره، سترګې وغړوه.› په هماغه شېبه زه بینا شوم او هغه مې ولیده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_13.mp3', '', 1761754199, 1761754199),
(34931, 'Acts 22:14', 'Acts', 22, 14, 'هغه وویل: ‹زمونږ د نیکونو خدای ته د دې دپاره غوره کړی یې چې د هغه رضا وپېژنې، د هغه نېک خدمتګار ووینې او د هغه اواز د هغه د خپلې خولې څخه واورې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_14.mp3', '', 1761754199, 1761754199),
(34932, 'Acts 22:15', 'Acts', 22, 15, 'ځکه چې ته به د ټولو خلکو دپاره د هغه شاهد اوسې او څه چې دې لیدلي او اورېدلي دي، د هغو شاهدي به ورکوې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_15.mp3', '', 1761754199, 1761754199),
(34933, 'Acts 22:16', 'Acts', 22, 16, 'اوس څه شي ته انتظار کوې؟ پاڅېږه، د تعمید غسل واخله او څښتن ته دعا وکړه چې ګناهونه دې وبخښل شي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_16.mp3', '', 1761754199, 1761754199),
(34934, 'Acts 22:17', 'Acts', 22, 17, 'کله چې زه بېرته اورشلیم ته راغلم او د خدای په کور کې مې دعا کوله، نو رویا مې ولیدله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_17.mp3', '', 1761754199, 1761754199),
(34935, 'Acts 22:18', 'Acts', 22, 18, 'په دې رویا کې مې څښتن ولیده چې راته ویل یې: ‹زر شه او سمدلاسه د اورشلیم څخه لاړ شه، ځکه چې د دې ښار خلک به زما په هکله ستا شاهدي ونه مني.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_18.mp3', '', 1761754199, 1761754199),
(34936, 'Acts 22:19', 'Acts', 22, 19, 'ما وویل: ‹څښتنه، هغوی په دې ښه پوهیږي چې زه هغه سړی یم چې ستا ایمانداران به مې زندان ته اچول او په هرې کنیسې کې به مې وهل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_19.mp3', '', 1761754199, 1761754199),
(34937, 'Acts 22:20', 'Acts', 22, 20, 'کله چې ستا شاهد استیفان ووژل شو، نو زه هلته ولاړ وم او په دې کار کې ورسره زما رضا وه او د هغه د قاتلانو د چپنو ساتنه مې کوله.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_20.mp3', '', 1761754199, 1761754199),
(34938, 'Acts 22:21', 'Acts', 22, 21, 'نو څښتن راته وویل: ‹لاړ شه، ځکه چې زه تا د لېرې ځایونو غیریهودیانو ته لېږم.›» پولوس رسول او رومي قوماندان', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_21.mp3', '', 1761754199, 1761754199),
(34939, 'Acts 22:22', 'Acts', 22, 22, 'خلکو تر دې ځای پورې د پولوس خبرو ته غوږ ونیوه، خو هغوی چیغې پیل کړې: «داسې سړی د دې نړۍ څخه ورک کړئ! هغه د دې لایق نه دی چې ژوندی پاتې شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_22.mp3', '', 1761754199, 1761754199),
(34940, 'Acts 22:23', 'Acts', 22, 23, 'هغوی چیغې وهلې، خپل څادرونه یې له ځمکې وهل او خاورې یې پورته بادولې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_23.mp3', '', 1761754199, 1761754199),
(34941, 'Acts 22:24', 'Acts', 22, 24, 'رومي قوماندان امر وکړ چې پولوس دننه نظامي‌قلعه ته بوځئ او په دورو یې ووهئ او پوښتنه ترې وکړئ، ترڅو دا معلومه شي چې خلک ولې د هغه په خلاف داسې چیغې وهي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_24.mp3', '', 1761754199, 1761754199),
(34942, 'Acts 22:25', 'Acts', 22, 25, 'خو کله چې هغوی پولوس وتاړه چې په دورو یې ووهي، نو پولوس د هغه منصبدار څخه چې په هغه ځای کې ولاړ ؤ، پوښتنه وکړه: «ایا تاسو ته قانون دا اجازه درکوي چې یو رومي سړی چې جرم هم ورباندې ثابت شوی نه وي، ووهئ؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_25.mp3', '', 1761754199, 1761754199),
(34943, 'Acts 22:26', 'Acts', 22, 26, 'کله چې هغه منصبدار دا خبره واورېدله، نو قوماندان ته ورغی او پوښتنه یې ترې وکړه: «ته پوهېږې چې څه کوې؟ دا سړی خو رومي دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_26.mp3', '', 1761754199, 1761754199),
(34944, 'Acts 22:27', 'Acts', 22, 27, 'نو قوماندان پولوس ته ورغی او پوښتنه یې ترې وکړه: «ماته ووایه چې ته رومي یې؟» پولوس ځواب ورکړ: «هو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_27.mp3', '', 1761754199, 1761754199),
(34945, 'Acts 22:28', 'Acts', 22, 28, 'قوماندان وویل: «ما په ډېره لوړه بیه دا تابعیت حاصل کړی دی.» پولوس ورته وویل: «خو زه رومي یم، ځکه چې مور او پلار مې رومیان دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_28.mp3', '', 1761754199, 1761754199),
(34946, 'Acts 22:29', 'Acts', 22, 29, 'نو کومو عسکرو چې غوښتل د پولوس څخه پوښتنې وکړي، هغه یې زر پرېښود او قوماندان هم ووېرېده، ځکه هغه پوه شو چې پولوس یو رومي سړی دی او د هغه په امر تړل شوی ؤ. پولوس د شورا په مخکې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_29.mp3', '', 1761754199, 1761754199),
(34947, 'Acts 22:30', 'Acts', 22, 30, 'په بله ورځ قوماندان وغوښتل په دې پوه شي چې په کوم معقول دلیل یهودیان په پولوس تور لګوي، نو پولوس یې ازاد کړ او مشرانو کاهنانو او ټولې شورا ته یې امر وکړ چې سره راټول شي. بیا هغه پولوس راوست او د هغوی په مخکې یې ودراوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts22_verse_30.mp3', '', 1761754199, 1761754199),
(34948, 'Acts 15:1', 'Acts', 15, 1, 'ځینې خلک د یهودیې څخه انطاکیې ته راغلل او ایماندارانو ته یې تعلیم ورکاوه او ویل یې: «که تاسو د موسی د شریعت له مخې سنت نه شئ، نو خلاصون نه شئ موندلی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts15_verse_1.mp3', '', 1761754199, 1761754199),
(34949, 'Acts 15:2', 'Acts', 15, 2, 'پولوس او برناباس د هغوی سره موافق نه وو او ډېر سخت بحث یې ورسره وکړ او پرېکړه یې وکړه چې پولوس او برناباس دې د نورو ایماندارانو سره اورشلیم ته لاړ شي او د دې موضوع په هکله دې د رسولانو او نورو مشرانو سره خبرې وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts15_verse_2.mp3', '', 1761754199, 1761754199),
(34950, 'Acts 15:3', 'Acts', 15, 3, 'هغوی د انطاکیې د کلیسا له خوا ولېږل شول او په داسې حال کې چې هغوی د فنیقیې او سامرې نه تېرېدل، ایمانداران یې خبرول چې څنګه غیریهودیانو ایمان راوړ. نو د دې خبر په اورېدلو ټول ایمانداران ډېر خوشحاله شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts15_verse_3.mp3', '', 1761754199, 1761754199),
(34951, 'Acts 15:4', 'Acts', 15, 4, 'کله چې پولوس او برناباس اورشلیم ته ورسېدل، نو د کلیسا د غړو، رسولانو او مشرانو له خوا ورته تود هرکلی وویل شو او بیا یې هغوی د هغو ټولو کارونو څخه خبر کړل چې خدای د هغوی په وسیله سرته رسولي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts15_verse_4.mp3', '', 1761754199, 1761754199),
(34952, 'Acts 15:5', 'Acts', 15, 5, 'خو د فریسیانو د ډلې ځینې ایمانداران راپاڅېدل او ویې ویل: «غیریهودیان باید سنت کړای شي او هغوی ته دې امر وشي چې د موسی په شریعت باندې عمل وکړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts15_verse_5.mp3', '', 1761754199, 1761754199),
