(34997, 'Colossians 4:10', 'Colossians', 4, 10, 'ارسترخوس چې زما سره په زندان کې دی، تاسو ته سلام وایي. همدارنګه مرقوس د برناباس د کاکا زوی هم تاسو ته سلام وایي. د مرقوس په هکله تاسو ته لارښوونې شوې وې چې که هغه تاسو ته راغی، نو هرکلی ورته ووایئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians4_verse_10.mp3', '', 1761754199, 1761754199),
(34998, 'Colossians 4:11', 'Colossians', 4, 11, 'او یسوعه چې د یوستوس په نوم هم یادیږي، هم درته سلام وایي. د یهودي ایماندارانو څخه یوازې دا درې کسان دي چې د خدای د پاچاهۍ په کار کې زما ملګرتیا کوي او هغوی ماته ډېره تسلي راکړې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians4_verse_11.mp3', '', 1761754199, 1761754199),
(34999, 'Colossians 4:12', 'Colossians', 4, 12, 'اپفراس چې ستاسو له ډلې څخه دی او د عیسی مسیح خدمتګار دی، تاسو ته سلام وایي. هغه تل تاسو ته په شوق او د زړه له کومي دعاګانې کوي، ترڅو تاسو د بالغو خلکو په توګه په ایمان کې ټینګ ودرېږئ او په کامله توګه د خدای په ارادې پوه شئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians4_verse_12.mp3', '', 1761754199, 1761754199),
(35000, 'Colossians 4:13', 'Colossians', 4, 13, 'نو زه شاهدي ورکوم چې هغه ستاسو دپاره او د هغو خلکو دپاره چې په لایودیکیه او هیراپولیس کې دي، ډېر زحمتونه ویستلي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians4_verse_13.mp3', '', 1761754199, 1761754199),
(35001, 'Colossians 4:14', 'Colossians', 4, 14, 'زمونږ ګران ډاکتر لوقا او دیماس هم تاسو ته سلامونه وایي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians4_verse_14.mp3', '', 1761754199, 1761754199),
(35002, 'Colossians 4:15', 'Colossians', 4, 15, 'هغو خویندو او ورونو ته چې په لایودیکیه کې دي او نیمفا او هغې کلیسا ته چې د هغې په کور کې ده، زما سلامونه ووایئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians4_verse_15.mp3', '', 1761754199, 1761754199),
(35003, 'Colossians 4:16', 'Colossians', 4, 16, 'کله چې تاسو ته دا لیک ولوستل شي، نو بیا یې د لایودیکیې کلیسا ته ولېږئ چې هغوی ته هم ولوستل شي او تاسو ته دې هغه لیک چې د لایودیکیې کلیسا ته لیکل شوی دی، هم ولوستل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians4_verse_16.mp3', '', 1761754199, 1761754199),
(35004, 'Colossians 4:17', 'Colossians', 4, 17, 'ارخیپوس ته ووایئ: «پام کوه، کومه وظیفه چې تاته د څښتن د خدمت دپاره سپارل شوې ده، هغه سرته ورسوه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians4_verse_17.mp3', '', 1761754199, 1761754199),
(35005, 'Colossians 4:18', 'Colossians', 4, 18, 'زه پولوس په خپل لاس تاسو ته دا سلام لیکم. په یاد مو وي چې زه لا تر‌اوسه په زندان کې یم. په تاسو دې د خدای فضل وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians4_verse_18.mp3', '', 1761754199, 1761754199),
(35006, 'Hebrews 10:1', 'Hebrews', 10, 1, 'د موسی شریعت د راتلونکو ښو شیانو یوازې یو تصویر دی او د هغو شیانو رښتینی شکل نه دی. دغه شریعت چې د هغه له مخې کومې قربانۍ چې هر کال به وړاندې کېدلې، هېڅکله نه شو کولای هغه خلک کامل کړي چې د خدای عبادت یې کاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_1.mp3', '', 1761754199, 1761754199),
(35007, 'Hebrews 10:2', 'Hebrews', 10, 2, 'که چېرې عبادت کوونکي په یوځل او د تل دپاره پاکېدلی، نو نور به هغوی خپل ځانونه ګناهکار نه ګڼلی او چا به نورې قربانۍ نه کولای.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_2.mp3', '', 1761754199, 1761754199),
(35008, 'Hebrews 10:3', 'Hebrews', 10, 3, 'بلکې دې قربانیو به هر کال هغوی ته خپل ګناهونه ور په یادول،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_3.mp3', '', 1761754199, 1761754199),
(35009, 'Hebrews 10:4', 'Hebrews', 10, 4, 'ځکه چې د غویانو او وزو وینه هېڅکله نه شي کولای ګناهونه لېرې کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_4.mp3', '', 1761754199, 1761754199),
(35010, 'Hebrews 10:5', 'Hebrews', 10, 5, 'له همدې امله کله چې مسیح نړۍ ته راتللو، نو خدای ته یې وویل: تا نه غوښتلې قربانۍ او نذرانې نو ماته دې راکړ بدن', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_5.mp3', '', 1761754199, 1761754199);